CREATE TABLE IF NOT EXISTS billing_day_status (instance_id VARCHAR(64) NOT NULL,bill_day DATE NOT NULL,active_job_id VARCHAR(40) NOT NULL,calculation_version VARCHAR(32) NOT NULL DEFAULT 'request-ledger-v1',status VARCHAR(24) NOT NULL DEFAULT 'complete',normal_requests BIGINT NOT NULL DEFAULT 0,anomaly_requests BIGINT NOT NULL DEFAULT 0,activated_at DATETIME(6) NOT NULL,PRIMARY KEY(instance_id,bill_day),KEY idx_billing_day_job(active_job_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
